     3	/// The selected clip's obscure regions on the canvas (spec §4.2, §11 CI-16):
     4	/// each one outlined through the layer's transform, with a move grip at its
     5	/// centre and eight resize handles, outside any modal mode. The session is
     6	/// `CanvasObscureSession` (one stored property on the frozen view,
     7	/// `obscureDrag`); the frozen file carries only the wiring — a press arm, a
     8	/// tick arm, a release arm, the cancel, one draw call and one cursor loop.
     9	///
    10	/// **Order.** The layer's own handles are hit first and a region grip is
    11	/// tried only when the press found a body or nothing
    12	/// (`CanvasHit.yieldsToObscureGrip`), so a grip under a layer handle is not
    13	/// reachable there; a region's inside is not a grip, so a drag there still
    14	/// moves the clip. The two modal modes' overlays sit above this whole view
    15	/// and take every press while armed; the outlines stay drawn under them.
    16	extension PreviewCanvasView {
    17	    /// The box whose regions are drawn: the primary box, with exactly one
    18	    /// clip selected, unlocked, outside crop mode and the text editor.
    19	    var obscureBox: CanvasLayerBox? {
    20	        guard selection.count == 1, !cropMode, editingClip == nil,
    21	              let box = primaryBox, !box.locked
    22	        else { return nil }
    23	        return box
    24	    }
    25	
    26	    /// The list a drag replaces — `editTarget`'s start state for the clip —
    27	    /// when it has as many entries as the list drawn (the recipe's, at the
    28	    /// playhead); nil otherwise, and then no grip exists, because an index
    29	    /// would name a different region.
    30	    var obscureStartList: [ObscureProps]? {
    31	        guard let box = obscureBox else { return nil }
    32	        let list = editTarget.start(of: box.clip, in: project).video.obscure
    33	        return list.count == box.video.obscure.count ? list : nil
    34	    }
    35	
    36	    /// The region grip under `point` (view space): the nearest within
    37	    /// `handleGrab` by the larger axis distance; a tie goes to the higher
    38	    /// index (the region drawn later), then to the earlier grip.
    39	    func obscureHit(at point: CGPoint) -> ObscureRegionHit? {
    40	        guard let box = obscureBox, !box.video.obscure.isEmpty, obscureStartList != nil else {
    41	            return nil
    42	        }
    43	        var best: (hit: ObscureRegionHit, distance: CGFloat)?
    44	        for (index, region) in box.video.obscure.enumerated() {
    45	            for grip in ObscureGrip.all {
    46	                let at = canvasToView(box.obscureGripPoint(grip, of: region))
    47	                let distance = max(abs(at.x - point.x), abs(at.y - point.y))
    48	                guard distance <= Self.handleGrab else { continue }
    49	                if let found = best {
    50	                    let closer = distance < found.distance
    51	                    let later = distance == found.distance && index > found.hit.index
    52	                    guard closer || later else { continue }
    53	                }
    54	                best = (ObscureRegionHit(clip: box.id, index: index, grip: grip), distance)
    55	            }
    56	        }
    57	        return best?.hit
    58	    }
    59	
    60	    /// Mouse-down on a grip (view space). False when the grip no longer
    61	    /// names an entry of the target's list, and the press falls through.
    62	    func beginObscureDrag(_ hit: ObscureRegionHit, at point: CGPoint) -> Bool {
    63	        guard let box = obscureBox, box.id == hit.clip, let list = obscureStartList else {
    64	            return false
    65	        }
    66	        gestureTarget = editTarget
    67	        guard let session = CanvasObscureSession(
    68	            hit: hit, list: list, frame: box, press: viewToCanvas(point))
    69	        else { return false }
    70	        obscureDrag = session
    71	        onLiveBegin?()
    72	        return true
    73	    }
    74	
    75	    /// One tick (canvas space): one live op, the whole list.
    76	    func continueObscureDrag(at point: CGPoint, flags: NSEvent.ModifierFlags) {
    77	        guard var session = obscureDrag else { return }
    78	        session.update(point: point, aboutCentre: flags.contains(.option))
    79	        obscureDrag = session
    80	        onLiveUpdate?([session.op(to: gestureTarget)])
    81	    }
    82	
    83	    // MARK: - Drawing
    84	
    85	    /// Every region's outline — a dark backing stroke, then the marquee's
    86	    /// dashed line — and, only while the grips exist, their handles and
    87	    /// centre crosses.
    88	    func drawObscureRegions() {
    89	        guard let box = obscureBox else { return }
    90	        let regions = box.video.obscure
    91	        guard !regions.isEmpty else { return }
    92	        let dash: [CGFloat] = [4, 3]
    93	        for region in regions {
    94	            let path = polygon(box.canvasQuad(ofSource: region.box))
    95	            NSColor.black.withAlphaComponent(0.4).setStroke()
    96	            path.lineWidth = 2
    97	            path.stroke()
    98	            path.setLineDash(dash, count: dash.count, phase: 0)
    99	            path.lineWidth = 1
   100	            DS.marquee.setStroke()
   101	            path.stroke()
   102	        }
   103	        guard obscureStartList != nil else { return }
   104	        for region in regions {
   105	            drawObscureCentre(canvasToView(box.obscureGripPoint(.move, of: region)))
   106	            drawHandles(
   107	                CanvasHandle.allCases.map { box.obscureGripPoint(.resize($0), of: region) },
   108	                fill: DS.marquee)
   109	        }
   110	    }
   111	
   112	    /// The move grip: a 10 pt cross over a dark backing, so it reads on a
   113	    /// white frame and a black one.
   114	    private func drawObscureCentre(_ centre: CGPoint) {
   115	        let arm: CGFloat = 5
   116	        let cross = NSBezierPath()
   117	        cross.move(to: CGPoint(x: centre.x - arm, y: centre.y))
   118	        cross.line(to: CGPoint(x: centre.x + arm, y: centre.y))
   119	        cross.move(to: CGPoint(x: centre.x, y: centre.y - arm))
   120	        cross.line(to: CGPoint(x: centre.x, y: centre.y + arm))
   121	        NSColor.black.withAlphaComponent(0.4).setStroke()
   122	        cross.lineWidth = 3
   123	        cross.stroke()
   124	        DS.marquee.setStroke()
   125	        cross.lineWidth = 1.5
   126	        cross.stroke()
   127	    }
   128	
   129	    /// A `handleGrab` square at every grip (view space), empty while the
   130	    /// grips do not exist.
   131	    func obscureCursorRects() -> [(rect: CGRect, cursor: NSCursor)] {
   132	        guard let box = obscureBox, !box.video.obscure.isEmpty, obscureStartList != nil else {
   133	            return []
   134	        }
   135	        let grab = Self.handleGrab
   136	        var rects: [(rect: CGRect, cursor: NSCursor)] = []
   137	        for region in box.video.obscure {
   138	            for grip in ObscureGrip.all {
   139	                let centre = canvasToView(box.obscureGripPoint(grip, of: region))
   140	                let rect = CGRect(
   141	                    x: centre.x - grab / 2, y: centre.y - grab / 2, width: grab, height: grab)
   142	                rects.append((rect, grip.cursor))
   143	            }
   144	        }
   145	        return rects
   146	    }
   147	}
/// it in exactly one place: the commit. The geometry below reads it only to
/// say whether the resolved frame is worth drawing.
enum CanvasRegionPurpose {
    /// `Z`, and the action lane's Zoom to Region button.
    case zoom
    /// The Obscure section's "Place on Canvas".
    case obscure
}

/// A rectangle dragged over the picture: the region a zoom action lands on,
/// or one `video.obscure` entry (spec §4.2, §4.3).
///
/// Both ends are held in CANVAS pixels — the space this whole file speaks —
/// and turned into source pixels only through the layer's box, so a rotated
/// or a cropped clip needs no special case here. The band itself drags FREE:
/// constraining it to the canvas's aspect would make `fill` unreachable from
/// the canvas, since a band that already has the canvas's shape fits and
/// fills identically. What keeps that honest is the resolved frame — the
/// rectangle that will actually be on screen when the zoom lands — which the
/// mode strokes beside the band while the drag is live, the same instinct as
/// the crop ghost.
struct ZoomRegionSession {
    let purpose: CanvasRegionPurpose
    /// The clip the region belongs to. The mode is armed for exactly one.
    let clip: UInt32
    /// Where the press landed, canvas pixels.
    let anchor: CGPoint
    var current: CGPoint
    /// ⇧ held during a ZOOM drag: the region covers the canvas rather than
    /// sitting inside it. It means nothing to an obscure region, which is
    /// the rectangle it is drawn as.
    var fill = false
    /// False until the pointer actually leaves the press point — a click
    /// that drew no rectangle must commit nothing, the `didMove` flag every
    /// session here carries.
    var didMove = false

    /// The smallest band that counts, in CANVAS pixels. A press with a
    /// twitch in it would otherwise ask the core to zoom to a region a
    /// fraction of a pixel wide, which is an `Err` naming `region.width`
    /// rather than the "nothing happened" it looks like.
    static let minBand: CGFloat = 6

    /// The dragged rectangle in canvas pixels, however the two corners lie.
    var canvasRect: CGRect {
        CGRect(
            x: min(anchor.x, current.x), y: min(anchor.y, current.y),
            width: abs(current.x - anchor.x), height: abs(current.y - anchor.y))
    }

    /// The flag is raised by MOVEMENT, not by the call: `mouseUp` runs this
    /// once more with the release point so the band ends where the pointer
    /// did, and a press-and-release that never moved must still read as the
    /// click it was.
    mutating func update(point: CGPoint, fill: Bool) {
        current = point
        self.fill = fill
        if point != anchor { didMove = true }
    }

    /// The band as a rectangle in the layer's own source-pixel frame — the
    /// min corner and the size, which `region(in:)` turns into the centre
    /// and size the op wants. Nil when the drag is too small to mean
    /// anything.
    ///
    /// All FOUR corners of the band are taken through `sourcePoint`, not the
    /// two the drag names: the band is axis-aligned in CANVAS space, so on a
    /// rotated layer its bounding box in Q is spanned by the other diagonal
    /// as much as by this one. At zero rotation the four collapse to the two
    /// and this is the rectangle that was dragged.
    func sourceRect(in box: CanvasLayerBox) -> CGRect? {
        let band = canvasRect
        guard didMove, band.width >= Self.minBand, band.height >= Self.minBand else { return nil }
        let corners = [
            CGPoint(x: band.minX, y: band.minY), CGPoint(x: band.maxX, y: band.minY),
            CGPoint(x: band.maxX, y: band.maxY), CGPoint(x: band.minX, y: band.maxY),
        ].map { box.sourcePoint($0) }
        guard let first = corners.first else { return nil }
        var minX = first.x, maxX = first.x, minY = first.y, maxY = first.y
        for point in corners.dropFirst() {
            minX = min(minX, point.x)
            maxX = max(maxX, point.x)
            minY = min(minY, point.y)
            maxY = max(maxY, point.y)
        }
        let rect = CGRect(x: minX, y: minY, width: maxX - minX, height: maxY - minY)
        guard rect.width > 0, rect.height > 0 else { return nil }
        return rect
    }

    /// The band as the op's region: the CENTRE and the size, in source
    /// pixels from the cropped rect's centre. Rounded the way every canvas
    /// gesture rounds what it writes.
    ///
    /// `ZoomRegion` is `add_zoom_action`'s argument type
    /// (`ReelCore.swift`), and it is what an `ObscureProps` is built from
    /// too: the two commits differ in where the four numbers go, never in
    /// what they mean. The centre is taken before the rounding rather than
    /// after, so a band rounded to whole pixels cannot drift half a pixel
    /// off the rectangle that was drawn.
    func region(in box: CanvasLayerBox) -> ZoomRegion? {
        guard let rect = sourceRect(in: box) else { return nil }
        return ZoomRegion(
            x: canvasRound(rect.midX), y: canvasRound(rect.midY),
            width: canvasRound(rect.width), height: canvasRound(rect.height))
    }

    /// The scale `add_zoom_action` will resolve for this band — `k = |cos θ|`,
    /// `m = |sin θ|`, and the two formulas `edit_zoom.rs`'s module doc
    /// derives, clamped into the layer's legal range exactly as the core
    /// clamps before it computes the offsets.
    /// With the pair above the section can only ever write the length it can
    /// see, so the guarantee holds; what it cannot promise is anything about a
    /// length a hand-written file or a `set_action_end` call put there.
    ///
    /// Do not fold this back into the single `set_action_end` it looks like.
    /// The two writes are the same shape from here and behave nothing alike
    /// three layers down, and every step of the failure is silent.
    ///
    /// Two residuals, both left deliberately and both smaller than what they
    /// replace:
    ///
    ///  - Changing an entry's DISCRIMINANT (a filter's `kind`, a region's
    ///    `kind` or `shape`) inside an action still writes the end patch,
    ///    because unlike a length change that IS a coherent animation —
    ///    `ENTRY_DISCRIMINANTS` in `actions.rs` holds the entry and switches
    ///    it at the end, which is what §5.4 says a discrete value does. It
    ///    reads back as unchanged until then, which is the inspector's
    ///    standing habit of showing the value AT THE PLAYHEAD while writing
    ///    the action's end, and not a property of lists.
    ///  - Adding or removing an entry while an action ALREADY animates that
    ///    list leaves the end patch at the old length, so that animation
    ///    degrades to a switch at the end until the end state is written
    ///    again. There is no way to say "drop this key" from here — a
    ///    `VideoPatch`'s list keys are single optionals, so nil is absent
    ///    rather than null — and a visible degradation is worth more than an
    ///    invisible append.
    private func structural(video patch: VideoPatch, for clip: ClipSnapshot)
        -> (base: VideoPatch?, animatable: VideoPatch?)
    {
        var base = VideoPatch()
        var animatable = patch
        if let filters = patch.filters,
            filters.count != editedList(clip, action: { $0.filters }, base: { $0.filters }).count
        {
            base.filters = filters
            animatable.filters = nil
        }
        if let obscure = patch.obscure,
            obscure.count != editedList(clip, action: { $0.obscure }, base: { $0.obscure }).count
        {
            base.obscure = obscure
            animatable.obscure = nil
        }
        // A curve is a list too (spec §11 GR-12, GR-32), but not this rule's:
        // every count animates (GR-34). The same count lerps per point, an
        // identity on either side is aligned to the other's x's
        // (`align_identity_curves`), and two curves of different counts blend
        // their values (`curve_blends`). So a curve write with an action
        // selected always goes to the END, a point added or deleted included,
        // and the curve is keyed and blends over the action.
        // Motion is not an animation target (the core refuses it in
        // `set_action_end`), so it ALWAYS lands on the base props.
        if patch.motion != nil {
            base.motion = patch.motion
            animatable.motion = nil
        }
        // A cutout's presence — a whole one or null — is the clip's (spec §11
        // CO-20, CO-30 (b)): an end refuses `subject`, `quality` and a null
        // cutout, so the Background section's checkbox and Reset land on the
        // base. Its sparse `cutoutPart` (Background, Edge, Feather) animates.
        if patch.cutout != nil {
            base.cutout = patch.cutout
            animatable.cutout = nil
        }
        // Hide while silent is not an animation target (spec §11 CO-92).
        if patch.hideSilent != nil {
            base.hideSilent = patch.hideSilent
            animatable.hideSilent = nil
        }
        // A cursor's `smoothing` and `hide_idle` are the clip's (spec §11 CU-30, CU-40): the
        // recipe reads them from the BASE, so an end carrying them would have no effect. Two
        // independent rules. (a) The clip's own keys go to the base; only the other six stay
        // in the end, an empty end part dropped. (b) An end key on a clip with no BASE cursor
        // also stores the defaults cursor on the base, merged with (a)'s keys, in the same
        // step — an end over no cursor switches at its end (CU-30), and with the defaults
        // stored Size and Ripple size animate. A whole cursor wins over `cursorPart` in
        // `VideoPatch.dictionary`, so (b)'s base carries (a)'s keys inside it.
        if let part = patch.cursorPart, !part.isEmpty {
            let own = part.clipsOwn
            let end = part.animatable
            if !own.isEmpty { animatable.cursorPart = end.isEmpty ? nil : end }
            if !end.isEmpty, clip.video?.cursor == nil {
                base.cursor = .some(
                    CursorProps(smoothing: own.smoothing ?? 0, hideIdle: own.hideIdle ?? nil))
            } else if !own.isEmpty {
                base.cursorPart = own
            }
        }
        return (base.isEmpty ? nil : base, animatable.isEmpty ? nil : animatable)
    }

constant int kMatteAlpha         = 1;
constant int kMatteAlphaInverted = 2;
constant int kMatteLuma          = 3;
constant int kMatteLumaInverted  = 4;

// What `amount = 1` means for each of the three filters whose strength is a
// LENGTH. All three are SOURCE pixels, the frame every other length on a
