407	   143	    /// (CO-90): the nearest container, outward from the layer's own, in
408	   144	    /// which one of them covers `t`.
409	   145	    fn gate_among(
410	   146	        &self,
411	   147	        instance: &Instance<'_>,
412	   148	        all: &[Instance<'_>],
413	   149	        gate: &HideSilent,
414	   150	        t: Ticks,
415	   151	        side: Side,
416	   152	    ) -> f64 {
417	   153	        let path: Vec<u32> = instance.inside.iter().map(|e| e.clip.id).collect();
418	   154	        let fade = gate.fade.max(0);
419	   155	        for depth in (0..=path.len()).rev() {
420	   156	            let container = path.get(..depth).unwrap_or(&[]);
421	   157	            let members: Vec<&Instance<'_>> =
422	   158	                all.iter().filter(|i| in_container(i, container)).collect();
423	   159	            if !members.iter().any(|i| covers(i.start, i.end, t, side)) {
424	   160	                continue;
425	   161	            }
426	   162	            let lo = t.saturating_sub(gate.hold.max(0)).saturating_sub(fade);
427	   163	            let hi = t.saturating_add(gate.pre_roll.max(0)).saturating_add(fade);
428	   164	            let spans = self.gate_spans(&members, gate, Some((lo, hi)));
429	   165	            return gate_over(&spans, fade, t, side);
430	   166	        }
431	   167	        1.0
432	   168	    }
