445	   181	    /// The plan's `gates` (CO-93): one `{clip, ramps}` per timeline-level
446	   182	    /// instance of a gated clip whose media has speech, the ramps tiling
447	   183	    /// its `[start, end)`, `coalesce`d. Empty when no clip has a gate, so
448	   184	    /// the plan writes no key.
449	   185	    pub(crate) fn gate_entries(&self) -> Vec<Value> {
450	   186	        let mut out = Vec::new();
451	   187	        for instance in self.all_instances() {
452	   188	            if !instance.inside.is_empty() {
453	   189	                continue;
454	   190	            }
455	   191	            let Some(gate) = self.live_gate(instance.clip) else {
456	   192	                continue;
457	   193	            };
458	   194	            let all = self.media_instances(gate.media);
459	   195	            let ramps = self.gate_ramps(&instance, &all, &gate);
460	   196	            let mut entry = Map::new();
461	   197	            entry.insert("clip".to_string(), Value::from(instance.clip.id));
462	   198	            entry.insert(
463	   199	                "ramps".to_string(),
464	   200	                Value::Array(ramps.iter().map(json).collect()),
