471	   207	    /// A timeline-level instance's gate as ramps over `[start, end)`: the
472	   208	    /// breakpoints are the instance's ends, every instance of the media's
473	   209	    /// ends, each merged span's `s − fade`, `s`, `e`, `e + fade`, and the
474	   210	    /// midpoint of two spans closer than `2·fade`, where one's fall meets
475	   211	    /// the next one's rise. Between two breakpoints the gate is a straight
476	   212	    /// line, read on the right at the start and on the left at the end.
477	   213	    fn gate_ramps(
478	   214	        &self,
479	   215	        instance: &Instance<'_>,
480	   216	        all: &[Instance<'_>],
481	   217	        gate: &HideSilent,
482	   218	    ) -> Vec<Ramp> {
483	   219	        let fade = gate.fade.max(0);
484	   220	        let members: Vec<&Instance<'_>> = all.iter().collect();
485	   221	        // Windowed as `gate_among` is, and exact by the same argument: an
486	   222	        // instance ending before `start − hold − fade` or starting after
487	   223	        // `end + pre_roll + fade` gives spans whose gate is 0 throughout
488	   224	        // `[start, end]`, so only the instance's neighbourhood is projected.
489	   225	        let lo = instance
490	   226	            .start
491	   227	            .saturating_sub(gate.hold.max(0))
492	   228	            .saturating_sub(fade);
493	   229	        let hi = instance
494	   230	            .end
495	   231	            .saturating_add(gate.pre_roll.max(0))
496	   232	            .saturating_add(fade);
497	   233	        let spans = self.gate_spans(&members, gate, Some((lo, hi)));
498	   234	        let mut breaks = vec![instance.start, instance.end];
499	   235	        for i in all {
500	   236	            breaks.extend([i.start, i.end]);
501	   237	        }
502	   238	        for &(s, e) in &spans {
503	   239	            breaks.extend([s.saturating_sub(fade), s, e, e.saturating_add(fade)]);
504	   240	        }
505	   241	        for pair in spans.windows(2) {
506	   242	            if let (Some(&(_, e1)), Some(&(s2, _))) = (pair.first(), pair.get(1)) {
507	   243	                if s2.saturating_sub(e1) < fade.saturating_mul(2) {
508	   244	                    breaks.push(e1.saturating_add(s2.saturating_sub(e1) / 2));
509	   245	                }
510	   246	            }
511	   247	        }
512	   248	        breaks.retain(|t| *t >= instance.start && *t <= instance.end);
513	   249	        breaks.sort_unstable();
514	   250	        breaks.dedup();
515	   251	        let ramps = breaks
516	   252	            .windows(2)
517	   253	            .filter_map(|pair| match (pair.first(), pair.get(1)) {
518	   254	                (Some(&a), Some(&b)) if b > a => Some(Ramp {
519	   255	                    start: a,
520	   256	                    duration: b.saturating_sub(a),
521	   257	                    from: self.gate_among(instance, all, gate, a, Side::Right),
522	   258	                    to: self.gate_among(instance, all, gate, b, Side::Left),
523	   259	                }),
524	   260	                _ => None,
525	   261	            })
526	   262	            .collect();
527	   263	        coalesce(ramps)
528	   264	    }
