548	     3	/// Hide while silent's line (format 43, spec §11 CO-93): over a clip with a
549	     4	/// gate, the gate the core multiplies its opacity by — the plan's `gates`
550	     5	/// entry, read through `TimelineView.gateCurves` — stroked across the clip's
551	     6	/// VIDEO region in teal, gate 1 at the top and 0 at the bottom, so a person
552	     7	/// sees where the camera fades out in each pause and back in before speech.
553	     8	///
554	     9	/// Inside an open nest the timeline's handle is the scope's, so a gate read
555	    10	/// from a container outside the nest is not drawn there (the recipe still
556	    11	/// applies it). An extension of `TimelineContentView` in a file of its own,
557	    12	/// as the duck line is: `TimelineView.swift` is frozen at wiring.
558	    13	extension TimelineContentView {
559	    14	    func drawGateLine(_ clip: ClipSnapshot, in rect: CGRect, owner: TimelineView, visible: CGRect) {
560	    15	        guard clip.video?.hideSilent != nil, rect.height >= 8, rect.width > 1,
561	    16	              let ramps = owner.gateCurves?.ramps(for: clip.id), !ramps.isEmpty
562	    17	        else { return }
563	    18	        let layout = owner.layout
564	    19	        // Flipped: the region's top is its minY, and gate 1 sits there.
565	    20	        func y(_ gate: Double) -> CGFloat {
566	    21	            rect.minY + 1 + CGFloat(1 - min(max(gate, 0), 1)) * (rect.height - 2)
567	    22	        }
568	    23	        let from = max(rect.minX, visible.minX) - 1
569	    24	        let to = min(rect.maxX, visible.maxX) + 1
570	    25	        guard to > from else { return }
571	    26	        // The core's ramps tile the clip's span, so the line is one polyline
572	    27	        // through every ramp that reaches the visible part; one off screen is
573	    28	        // skipped, the ramps being in order.
574	    29	        let path = NSBezierPath()
575	    30	        var started = false
576	    31	        for ramp in ramps {
577	    32	            let start = layout.x(for: ramp.start)
578	    33	            let end = layout.x(for: ramp.start + ramp.duration)
579	    34	            guard end >= from, start <= to else { continue }
580	    35	            let head = CGPoint(x: start, y: y(ramp.from))
581	    36	            if started { path.line(to: head) } else { path.move(to: head) }
582	    37	            started = true
583	    38	            path.line(to: CGPoint(x: end, y: y(ramp.to)))
584	    39	        }
585	    40	        guard started else { return }
586	    41	        NSGraphicsContext.current?.saveGraphicsState()
587	    42	        NSBezierPath(rect: rect).addClip()
588	    43	        NSColor.systemTeal.withAlphaComponent(0.9).setStroke()
589	    44	        path.lineWidth = 1
590	    45	        path.stroke()
591	    46	        NSGraphicsContext.current?.restoreGraphicsState()
592	    47	    }
593	    48	}
