183	    23	    /// `HIDE_SILENT_*`).
184	    24	    static let defaultPreRoll: Ticks = 120_000
185	    25	    static let defaultHold: Ticks = 900_000
186	    26	    static let defaultFade: Ticks = 180_000
187	    27	    static let maxTicks: Ticks = 3_000_000
