189	    29	    init(
190	    30	        media: UInt32, preRoll: Ticks = defaultPreRoll, hold: Ticks = defaultHold,
191	    31	        fade: Ticks = defaultFade
192	    32	    ) {
193	    33	        self.media = media
194	    34	        self.preRoll = preRoll
