202	    42	        preRoll = c.lenient(.preRoll, Self.defaultPreRoll)
203	    43	        hold = c.lenient(.hold, Self.defaultHold)
204	    44	        fade = c.lenient(.fade, Self.defaultFade)
205	    45	    }
