214	    54	/// The media the Hide While Silent section offers for "Speech from" (CO-94).
215	    55	enum HideSilentSources {
216	    56	    /// The media with sound of any clip in `snapshot` (the selected clips
217	    57	    /// included) whose span overlaps a selected clip's: picture-less media
218	    58	    /// first — the microphone first — then by total overlap with the
219	    59	    /// selected clips, longest first, then by id.
220	    60	    static func candidates(
221	    61	        for clips: [ClipSnapshot], in snapshot: ProjectSnapshot
222	    62	    ) -> [MediaSnapshot] {
223	    63	        var overlap: [UInt32: Ticks] = [:]
224	    64	        for other in snapshot.clips {
225	    65	            guard case .media = other.source, let media = snapshot.media(for: other),
226	    66	                  media.hasAudio
227	    67	            else { continue }
228	    68	            for clip in clips {
229	    69	                let shared = min(other.end, clip.end) - max(other.start, clip.start)
230	    70	                if shared > 0 { overlap[media.id, default: 0] += shared }
231	    71	            }
232	    72	        }
233	    73	        return overlap.keys.compactMap { snapshot.media($0) }.sorted { a, b in
234	    74	            if a.hasVideo != b.hasVideo { return !a.hasVideo }
235	    75	            let (oa, ob) = (overlap[a.id] ?? 0, overlap[b.id] ?? 0)
236	    76	            if oa != ob { return oa > ob }
237	    77	            return a.id < b.id
238	    78	        }
239	    79	    }
